# Generated by Descant: acceptance tests.

# frozen_string_literal: true
require "rails_helper"

RSpec.describe "Timekeeping relay test hooks" do
  it "a relay paused through the hook sends nothing until resumed, then delivers the waiting row" do
    hook_service_token = "service-#{SecureRandom.hex(24)}"
    deliveries = 0
    WebMock.stub_request(:post, %r{\Ahttp://snapshots\.test}).to_return do
      deliveries += 1
      { status: 200, headers: { "Content-Type" => "application/json" }, body: JSON.generate(applied: 1, ignored: 0) }
    end
    position = OutboxSnapshot.insert_all!([{
      "id" => 501, "project_id" => 5, "user_id" => 6, "work_date" => Date.new(2026, 3, 2), "duration" => 60.0,
      "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false, "source" => "manual",
      "source_metadata" => {}, "proof_metadata" => {}, "created_at" => Time.utc(2026, 3, 2),
      "updated_at" => Time.utc(2026, 3, 2), "company_id" => 1, "version" => 1, "generation" => 1
    }], returning: %w[outbox_position]).first.fetch("outbox_position")
    auth = { "Authorization" => "Bearer #{hook_service_token}" }

    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => hook_service_token,
      Timekeeping::Environment::MONOLITH_SNAPSHOT_URL => "http://snapshots.test"
    ) do
      post "/internal/v1/test-hooks/relay/pause", headers: auth
      expect(response.status).to be_between(200, 299)
      RelayJob.perform_now

      # "A paused relay sends nothing until resumed"
      expect(deliveries).to eq(0)
      expect(OutboxSnapshot.find(position).sent_at).to be_nil

      post "/internal/v1/test-hooks/relay/resume", headers: auth
      expect(response.status).to be_between(200, 299)
      RelayJob.perform_now

      expect(deliveries).to eq(1)
      expect(OutboxSnapshot.find(position).sent_at).not_to be_nil
    ensure
      post "/internal/v1/test-hooks/relay/resume", headers: auth
    end
  end

  it "refuses a pause request without the service token" do
    hook_service_token = "service-#{SecureRandom.hex(24)}"
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => hook_service_token
    ) do
      post "/internal/v1/test-hooks/relay/pause"
    end

    expect([response.status, response.parsed_body]).to eq([401, { "reason" => "unauthorized" }])
  end
end
